// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.HashSet;
import java.util.Set;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.inferencer.InferencerConnection;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class MemoryStoreNoneTransactionTest {
	private static final SimpleValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VALUE_FACTORY.createIRI("urn:memory:none:predicate");

	@Test
	void noneTransactionCommitsExplicitAndInferredRowsAndAllowsFollowup() throws Exception {
		MemoryStore store = new MemoryStore();
		store.init();
		try {
			try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
				Statement inferred = statement("first-inferred", "inferred-value");
				Statement explicit = statement("first-explicit", "explicit-value");
				connection.begin(IsolationLevels.NONE);
				assertTrue(addInferred(connection, inferred), "the inferred row must enter the NONE transaction");
				connection.addStatement(explicit.getSubject(), explicit.getPredicate(), explicit.getObject());
				connection.commit();

				assertStatements(connection, false, Set.of(explicit),
						"only explicit rows are visible to explicit reads");
				assertStatements(connection, true, Set.of(explicit, inferred),
						"the committed NONE transaction must expose its exact explicit and inferred rows");

				Statement nextInferred = statement("followup-inferred", "next-inferred-value");
				Statement nextExplicit = statement("followup-explicit", "next-explicit-value");
				connection.begin(IsolationLevels.NONE);
				assertTrue(addInferred(connection, nextInferred),
						"a follow-up NONE transaction must accept inferred rows");
				connection.addStatement(nextExplicit.getSubject(), nextExplicit.getPredicate(),
						nextExplicit.getObject());
				connection.commit();

				assertStatements(connection, false, Set.of(explicit, nextExplicit),
						"follow-up commits must retain exact explicit rows");
				assertStatements(connection, true, Set.of(explicit, inferred, nextExplicit, nextInferred),
						"follow-up commits must retain exact mixed rows");
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void noneRollbackDiscardsPromotionAndConnectionCanCommitAfterward() throws Exception {
		MemoryStore store = new MemoryStore();
		store.init();
		try {
			try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
				Statement promoted = statement("promoted", "same-value");
				connection.begin(IsolationLevels.NONE);
				assertTrue(addInferred(connection, promoted), "the inferred row must be admitted before promotion");
				connection.addStatement(promoted.getSubject(), promoted.getPredicate(), promoted.getObject());
				// Keep duplicate admission exercised; its boolean uses datasets retained before these writes.
				addInferred(connection, promoted);
				connection.rollback();
				assertStatements(connection, false, Set.of(),
						"rollback must remove the uncommitted explicit promotion");
				assertStatements(connection, true, Set.of(), "rollback must remove the uncommitted inferred row");

				Statement afterRollbackInferred = statement("after-rollback-inferred", "inferred-value");
				Statement afterRollbackExplicit = statement("after-rollback-explicit", "explicit-value");
				connection.begin(IsolationLevels.NONE);
				assertTrue(addInferred(connection, afterRollbackInferred),
						"the same connection must accept inferred work after rollback");
				connection.addStatement(afterRollbackExplicit.getSubject(), afterRollbackExplicit.getPredicate(),
						afterRollbackExplicit.getObject());
				connection.commit();

				assertStatements(connection, false, Set.of(afterRollbackExplicit),
						"the post-rollback explicit commit must publish exactly its explicit row");
				assertStatements(connection, true, Set.of(afterRollbackExplicit, afterRollbackInferred),
						"the post-rollback commit must publish exactly its mixed rows");
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void noneTransactionCommitsSameTermInferredToExplicitPromotion() throws Exception {
		MemoryStore store = new MemoryStore();
		store.init();
		try {
			try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
				Statement promoted = statement("committed-promotion", "same-value");
				connection.begin(IsolationLevels.NONE);
				assertTrue(addInferred(connection, promoted), "the row must first be admitted as inferred");
				connection.addStatement(promoted.getSubject(), promoted.getPredicate(), promoted.getObject());
				// Keep duplicate admission exercised; its boolean uses datasets retained before these writes.
				addInferred(connection, promoted);
				connection.commit();

				assertStatements(connection, false, Set.of(promoted),
						"the promoted row must be visible as an exact explicit result");
				assertStatements(connection, true, Set.of(promoted),
						"the promoted row must appear once in the combined result");
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	void persistentNoneCommitRestoresExactExplicitAndInferredRows(@TempDir Path dataDir) throws Exception {
		Statement inferred = statement("persistent-inferred", "inferred-value");
		Statement explicit = statement("persistent-explicit", "explicit-value");
		MemoryStore store = new MemoryStore(dataDir.toFile());
		store.init();
		try {
			try (InferencerConnection connection = (InferencerConnection) store.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				assertTrue(addInferred(connection, inferred), "the persistent transaction must admit its inferred row");
				connection.addStatement(explicit.getSubject(), explicit.getPredicate(), explicit.getObject());
				connection.commit();
				assertStatements(connection, false, Set.of(explicit),
						"the live persistent store must expose its explicit row");
				assertStatements(connection, true, Set.of(explicit, inferred),
						"the live persistent store must expose the exact mixed result");
			}
		} finally {
			store.shutDown();
		}

		MemoryStore reopened = new MemoryStore(dataDir.toFile());
		reopened.init();
		try {
			try (InferencerConnection connection = (InferencerConnection) reopened.getConnection()) {
				assertStatements(connection, false, Set.of(explicit), "reopen must restore exactly the explicit row");
				assertStatements(connection, true, Set.of(explicit, inferred),
						"reopen must restore the exact mixed explicit and inferred rows");
			}
		} finally {
			reopened.shutDown();
		}
	}

	private static boolean addInferred(InferencerConnection connection, Statement statement) throws Exception {
		Resource context = statement.getContext();
		return connection.addInferredStatement(statement.getSubject(), statement.getPredicate(), statement.getObject(),
				context);
	}

	private static Statement statement(String subject, String object) {
		return VALUE_FACTORY.createStatement(VALUE_FACTORY.createIRI("urn:memory:none:" + subject), PREDICATE,
				VALUE_FACTORY.createLiteral(object));
	}

	private static void assertStatements(InferencerConnection connection, boolean includeInferred,
			Set<Statement> expected, String message) throws Exception {
		Set<Statement> actual = new HashSet<>();
		int count = 0;
		try (CloseableIteration<? extends Statement> rows = connection.getStatements(null, null, null,
				includeInferred)) {
			while (rows.hasNext()) {
				count++;
				assertTrue(actual.add(rows.next()), message + ": duplicate statement in result");
			}
		}
		assertEquals(expected.size(), count, message + ": exact result cardinality");
		assertEquals(expected, actual, message + ": exact result rows");
	}
}
